  const now = Date.now();
  const result = { channel, lookaheadHours, estimateAgeDays, invoiceAgeDays, renewalDays, appointments: { eligible: 0, queued: 0, duplicates: 0 }, estimates: { eligible: 0, queued: 0, duplicates: 0 }, invoices: { eligible: 0, queued: 0, duplicates: 0 }, plans: { eligible: 0, queued: 0, duplicates: 0 } };
  const mayManageSales = claims.role === 'owner' || claims.role === 'dispatcher';
  const mayManageReceivables = claims.role === 'owner' || claims.role === 'accountant';
