    const plans = saved.plans.filter((plan) => plan.status === 'Active' && plan.customerId && Number.isFinite(Date.parse(plan.renewalAt)) && Date.parse(plan.renewalAt) >= now && Date.parse(plan.renewalAt) <= planHorizon);
